        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by dereferencing a NULL pointer when the `port` variable was not properly checked before being used in the `put_device()` function. This could lead to undefined behavior or crashes if `port` was NULL, which was identified by the coccicheck warning. The logic did not account for the scenario where `find_cxl_port(dport_dev)` could return NULL, leading to the dereference error.

        Commit message:
        cxl/core/port: Fix NULL but dereferenced coccicheck error

Fix the following coccicheck warning:
./drivers/cxl/core/port.c:913:21-24: ERROR: port is NULL but dereferenced.

The put_device() is only relevent in the is_cxl_root() case.

Fixes: 2703c16c75ae ("cxl/core/port: Add switch port enumeration")
Signed-off-by: Wan Jiabing <wanjiabing@vivo.com>
Link: https://lore.kernel.org/r/20220307094158.404882-1-wanjiabing@vivo.com
Signed-off-by: Dan Williams <dan.j.williams@intel.com>  

        Patch:

 static void cxl_detach_ep(void *data)
 {
 	struct cxl_memdev *cxlmd = data;
 	struct device *iter;

 	for (iter = &cxlmd->dev; iter; iter = grandparent(iter)) {
 		struct device *dport_dev = grandparent(iter);
 		struct cxl_port *port, *parent_port;
 		LIST_HEAD(reap_dports);
 		struct cxl_ep *ep;

 		if (!dport_dev)
 			break;

 		port = find_cxl_port(dport_dev);
-		if (!port || is_cxl_root(port)) {
+		if (!port)
+			continue;
+
+		if (is_cxl_root(port)) {
 			put_device(&port->dev);
 			continue;
 		}

 		parent_port = to_cxl_port(port->dev.parent);
 		cxl_device_lock(&parent_port->dev);
 		if (!parent_port->dev.driver) {
 			/*
 			 * The bottom-up race to delete the port lost to a
 			 * top-down port disable, give up here, because the
 			 * parent_port ->remove() will have cleaned up all
 			 * descendants.
 			 */
 			cxl_device_unlock(&parent_port->dev);
 			put_device(&port->dev);
 			continue;
 		}

 		cxl_device_lock(&port->dev);
 		ep = find_ep(port, &cxlmd->dev);
 		dev_dbg(&cxlmd->dev, "disconnect %s from %s\n",
 			ep ? dev_name(ep->ep) : "", dev_name(&port->dev));
 		cxl_ep_release(ep);
 		if (ep && !port->dead && list_empty(&port->endpoints) &&
 		    !is_cxl_root(parent_port)) {
 			/*
 			 * This was the last ep attached to a dynamically
 			 * enumerated port. Block new cxl_add_ep() and garbage
 			 * collect the port.
 			 */
 			port->dead = true;
 			list_splice_init(&port->dports, &reap_dports);
 		}
 		cxl_device_unlock(&port->dev);

 		if (!list_empty(&reap_dports)) {
 			dev_dbg(&cxlmd->dev, "delete %s\n",
 				dev_name(&port->dev));
 			delete_switch_port(port, &reap_dports);
 		}
 		put_device(&port->dev);
 		cxl_device_unlock(&parent_port->dev);
 	}
 }



